                  "text": "A Xiaotashan, vagyis a Kis Torony-hegy, egy meredek, sziklás hegycsúcs, amely arról a zord sziklaalakzatokról ismert, amelyek a sűrű tűlevelű lombkoronából emelkednek ki.",
